import{_ as a,c as o,o as t,ag as i}from"./chunks/framework.DfL_BkQ-.js";const u=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md","lastUpdated":1791309864000}'),r={name:"guide/installation.md"};function s(n,e,l,d,c,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>nPlyr ships as two targets from one Xcode project:</p><ul><li><strong><code>nPlyr</code></strong> — the macOS app.</li><li><strong><code>nPlyrIOS</code></strong> — the iOS / iPadOS app.</li></ul><p>Both share the same playback core and rule engine.</p><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h2><h3 id="mac-app-store-recommended" tabindex="-1">Mac App Store (recommended) <a class="header-anchor" href="#mac-app-store-recommended" aria-label="Permalink to &quot;Mac App Store (recommended)&quot;">​</a></h3><ol><li>Open the <strong>Mac App Store</strong> and search for <strong>nPlyr</strong>, or use the badge on the <a href="/">home page</a>.</li><li>Click <strong>Get</strong> and wait for the download to finish.</li><li>Launch nPlyr from the Dock or Launchpad.</li></ol><p>The Mac App Store build is sandboxed and signed by Apple, so no extra setup is required.</p><h3 id="sideload-development-testflight" tabindex="-1">Sideload (development / TestFlight) <a class="header-anchor" href="#sideload-development-testflight" aria-label="Permalink to &quot;Sideload (development / TestFlight)&quot;">​</a></h3><p>If you build from source, open <code>nPlyr.xcodeproj</code>, select the <strong><code>nPlyr</code></strong> scheme and run on &quot;My Mac&quot;. A development-signed build may prompt you to grant the permissions described in <a href="/guide/permissions.html">Permissions</a> the first time you use the browser or downloads.</p><h2 id="ios-ipados" tabindex="-1">iOS / iPadOS <a class="header-anchor" href="#ios-ipados" aria-label="Permalink to &quot;iOS / iPadOS&quot;">​</a></h2><h3 id="app-store" tabindex="-1">App Store <a class="header-anchor" href="#app-store" aria-label="Permalink to &quot;App Store&quot;">​</a></h3><p>Search <strong>nPlyr</strong> on the iOS App Store and install. The same account unlocks the mini-program features on both platforms.</p><h3 id="build-from-source" tabindex="-1">Build from source <a class="header-anchor" href="#build-from-source" aria-label="Permalink to &quot;Build from source&quot;">​</a></h3><ol><li>Open <code>nPlyr.xcodeproj</code> and select the <strong><code>nPlyrIOS</code></strong> scheme.</li><li>Choose a simulator or a connected device (iOS 16+).</li><li>Run. On a physical device you need a development team set in Signing &amp; Capabilities.</li></ol><blockquote><p>The iOS build uses the same shared sources as macOS; only the small platform-glue files differ. There is no separate <code>ffmpeg</code> dependency.</p></blockquote><h2 id="first-launch" tabindex="-1">First launch <a class="header-anchor" href="#first-launch" aria-label="Permalink to &quot;First launch&quot;">​</a></h2><p>On first launch nPlyr:</p><ul><li>asks for the permissions it needs (see <a href="/guide/permissions.html">Permissions</a>),</li><li>creates the local media library under your user data container,</li><li>defaults to your system language (switchable anytime in <a href="/guide/settings.html">Settings</a>).</li></ul><p>If something does not behave as expected after install, jump to <a href="/guide/troubleshooting.html">Troubleshooting</a>.</p>',20)])])}const m=a(r,[["render",s]]);export{u as __pageData,m as default};
